WHERE cricos_course_code = '0100860';

UPDATE courses SET
    course_description = '<p>Build the skills to understand, investigate and respond to cybercrime with La Trobe''s Bachelor of Cybersecurity/Bachelor of Criminology. </p><p>In this double degree, you will explore crime as a social issue while learning how to manage and protect online information, systems and networks. You will study areas such as cybersecurity fundamentals, Python programming, cyber risk management and incident response, ethical hacking, criminal law, cyber law and policy, forensic science and justice systems. </p><p>Through labs, simulations, AI-informed threat detection activities, digital forensics activities and case-based learning, you will apply technical and investigative skills to real-world cybercrime challenges. </p><p>By studying the Bachelor of Cybersecurity/Bachelor of Criminology, you will learn how to: </p><ul><li>analyse cybercrime through technical, legal, ethical and social perspectives </li></ul><ul><li>interpret the social, cultural, political and economic factors that shape crime </li></ul><ul><li>evaluate Australian and international cyber law, policy and justice systems </li></ul><ul><li>use Python programming, cyber algorithms, AI-informed threat detection and digital forensics to investigate cybersecurity challenges </li></ul><ul><li>assess how emerging technologies affect security, justice, privacy and digital regulation. </li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 7 - Bachelor Degree.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 168000,
    onshore_tuition_fee = 42000,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>Units 3 and 4: a study score of at least 25 in English (EAL) or at least 20 in English other than EAL.</td></tr><tr><td><strong>English Proficiency</strong></td><td>6.5 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '0100861';

UPDATE courses SET
    course_description = '<p>Harness key AI technologies driving change and sparking innovation in a range of industries with La Trobe''s Master of Artificial Intelligence.</p><p>Explore subjects in IT fundamentals, machine learning, data mining, computer vision, cybersecurity and natural language processing (NLP). Complement your AI expertise with transferable skills in entrepreneurship, professional practice and project management.</p><p>By studying La Trobe''s Master of Artificial Intelligence, you will:</p><ul><li>explore deep-learning techniques and how they can aid AI functions such as image recognition, machine translation and speech synthesis</li><li>learn how to use research skills and deep-learning algorithms to develop AI-based solutions to real-world problems</li><li>gain an understanding of the moral and societal issues faced by today''s IT industry and the impact of how AI technology is used</li><li>choose an industry development project or work-based placement to cement your learning and launch your career, or pursue an applied research project or industry-based thesis</li><li>benefit from the first-hand knowledge and experience of your teachers, including world-renowned AI researchers</li><li>have the flexibility to exit early with a Graduate Diploma after one year or a Graduate Certificate after six months or, depending on your previous computer science or IT qualifications, complete your Master''s in only 1.5 years.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
    course_duration_per_week = 104,
