    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '0100864';

UPDATE courses SET
    course_description = '<p>You will graduate from this degree as a midwife who is qualified to provide leadership in advanced clinical, management, research and academic aspects of the provision of health services.</p><p>You will possess a unique blend of abilities stemming from clinical experience, rigorous intellectual development and participation in the study of issues significant to midwifery. The degree offers an integrated program of research with supporting coursework in the first year. Through a combination of core and elective subjects, you will gain knowledge and skills in designing and conducting research, literature review techniques, critical analysis and writing for publication, as well as opportunities to apply these skills in clinical or professional projects of relevance to nursing.</p><p>The research component requires you to pursue an independent and sustained investigation into a research problem that will culminate in the submission of a thesis for examination of 60,000 words.</p><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 10 – Professional Doctorate.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 170400,
    onshore_tuition_fee = 42600,
    enrolment_fee = 0,
    materials_fee = NULL,
