    apply_form = 'https://www.latrobe.edu.au/study/apply/research',
    updated_at = NOW()
WHERE cricos_course_code = '0101141';

UPDATE courses SET
    course_description = '<p>Help people maximise their quality of life and reach their full potential with La Trobe''s Bachelor of Occupational Therapy (Honours).</p><p>Discover the science behind human activity and get the know-how to conduct evidence-based occupational therapy assessments and interventions for people of all ages and backgrounds. Learn with a combination of face-to-face tutorials and workshops, online learning and hands-on experience, including 1,000 hours of professional placements.</p><p>By studying La Trobe''s Bachelor of Occupational Therapy (Honours), you will:</p><ul><li>gain essential knowledge in occupational science, anatomy, physiology and psychology</li><li>uncover the best treatment options for people with special needs and chronic conditions</li><li>explore communication as a foundation to your practice as a health professional</li><li>learn about group theory, process and development</li><li>understand cultural identity and responsiveness in relation to health and wellbeing, including First Nations'' perspectives</li><li>apply your learning with individuals and families and collaborate with employers, policymakers and other health professionals</li><li>build skills in both qualitative and quantitative research design, then pursue an applied research project or industry-based thesis in your embedded Honours year</li><li>graduate eligible to apply for registration with the Occupational Therapy Board of Australia (OTBA).</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 – Bachelor Degree Honours.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 184800,
    onshore_tuition_fee = 46200,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = 'Academic Requirements<p>Units 3 and 4: a study score of at least 30 in English (EAL) or at least 25 in English other than EAL.</p> English Language Requirements<p>7.0 IELTS (Academic) with no individual band less than 7.0.</p><br/><p>Please refer to our <a href="https://www.latrobe.edu.au/study/apply/international/requirements">Language requirements</a> page for details of other accepted English proficiency tests and additional recognised English language proficiency measures, such as English as the language of instruction.</p><br/><p>IELTS, TOEFL, PTE, OET are the only English Proficiency tests accepted for entry into this course.</p>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '0101261';

UPDATE courses SET
    course_description = '<p><strong>Become a fully-qualified physiotherapist.</strong></p><p>Movement is essential to our health, happiness and connection to others - and physios help us move better. Get ready to use exercise and movement to improve the lives of athletes, children, adults and people recovering from surgery, injury or illness.</p><p>With La Trobe''s Bachelor of Physiotherapy (Honours) you''ll get a detailed understanding of the human body and develop the practical skills to launch your career in this rewarding and dynamic field of health. At La Trobe, not only will you learn from industry leaders and world-class researchers, you''ll experience unique industry opportunities with our broad range of partners.</p><p>Start building your practical skills as soon as you start first year and finish your degree with clinical training equivalent to six months of workplace experience. Graduate work ready and in-demand as a fully-qualified physiotherapist and step into your first job.</p><p>Throughout the course you''ll gain quality hands-on experience with placements at leading hospitals and private practices. You could find yourself in acute hospital units, rehabilitation facilities, community health clinics, private practice, sporting organisations, educational facilities or research centres.</p><p>Choose to take your physiotherapy degree global with international placement or study opportunities - like students before you who''ve experienced Denmark, Italy, Vietnam and India. Or keep it local with placements throughout Melbourne and regional Victoria.</p><p>In your Honours year, you''ll undertake research or industry-based project work where you''ll solve real problems relating to human health and physical performance.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Bioscience</strong><ul><li>Gain an intricate understanding of the human body through the study of anatomy, physiology, pathology, biomechanics of human movement and pharmacology.</li></ul></li><li><strong>Physiotherapy skills</strong><ul><li>Discover how to assess, diagnose and improve people''s movement, health and quality of life.</li></ul></li><li><strong>Specialised areas</strong><ul><li>Learn how to apply your physiotherapy skills to help people with a variety of conditions which relate to cardiorespiratory, musculoskeletal, sports, neurological, women''s, men''s, paediatric and aged care health.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 – Bachelor Degree Honours.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 232800,
    onshore_tuition_fee = 58200,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = 'Academic Requirements<p>Units 3 and 4: a study score of at least 30 in English (EAL) or at least 25 in English other than EAL.</p><p>Units 3 and 4: a study score of at least 25 in two of Biology, Chemistry, Physics, General Mathematics, Mathematics Methods, Specialist Mathematics or Physical Education.</p> English Language Requirements<p>7.0 IELTS (Academic) with no individual band less than 7.0.</p><br/><p>Please refer to our <a href="https://www.latrobe.edu.au/study/apply/international/requirements">Language requirements</a> page for details of other accepted English proficiency tests and additional recognised English language proficiency measures, such as English as the language of instruction.</p>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '0101262';

UPDATE courses SET
    course_description = '<p>As a social worker, you''ll provide support and assistance to people and families in need. La Trobe''s Bachelor of Social Work (Honours) gives you the clinical knowledge and hands-on skills to launch your career.</p><p>You''ll learn from world-renowned academics about promoting human rights and the importance of social justice. Our diverse range of subjects provide foundations in both psychology and sociology. Two 14-week placements enable you to put your knowledge and skills into practice and gain professional experience within leading health and welfare organisations in Victoria.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Sociology and society</strong><ul><li>Discover the cultural changes that shaped Australian society and how individuals connect with each other.</li></ul></li><li><strong>Introductory psychology</strong><ul><li>Study they key areas of psychology and explore how diverse contexts affect individuals in different ways. Discover how your brain helps to create your behaviour, and how your brain and behaviour change across your lifespan.</li></ul></li><li><strong>Human services</strong><ul><li>Explore the values, ethics and practice of social work and human services.</li></ul></li><li><strong>Social work and inequality</strong><ul><li>Study the issues of inequality and their impact on people''s wellbeing.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 – Bachelor Degree Honours.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 145600,
    onshore_tuition_fee = 36400,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>Units 3 and 4: a study score of at least 30 in English (EAL) or at least 25 in English other than EAL.</td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>Please refer to our Language requirements page for details of other accepted English proficiency tests and additional recognised English language proficiency measures, such as English as the language of instruction.</li><li>7.0 IELTS (Academic) with no individual band less than 7.0.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '0101263';

UPDATE courses SET
    course_description = '<p><strong>Help others find their voice.</strong></p><p>Our ability to communicate clearly and enjoy food or drink are things we can take for granted. But people of all ages can experience difficulties and the effects can be devastating. Speech pathologists work to improve a person''s abilities, they also work to improve quality of life. Launch your career in this rewarding field of health with La Trobe''s Bachelor of Speech Pathology (Honours).</p><p>You''ll develop an understanding of the anatomy behind speech and swallowing impairments and provide therapeutic treatment and management options. Build hands-on skills with approximately 1,000 hours of placement on-campus and in clinics across Victoria. You''ll also learn how to improve speech pathology services and policies by tackling a fourth-year industry project or research thesis.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Therapeutic intervention and management</strong></li><li><ul><li>Design and manage the best course of treatment for patients with communication and swallowing impairments.</li></ul></li><li><strong>Anatomy and neurophysiology</strong></li><li><ul><li>Gain an understanding of the functional anatomy and neurophysiology relevant to communication and swallowing and their role in impairment.</li></ul></li><li><strong>The science of speech and hearing</strong></li><li><ul><li>Discover the latest techniques for investigating sound, speech, and hearing, including the analysis of sound waves and speech, and the psychology of sound perception.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 – Bachelor Degree Honours</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 209600,
    onshore_tuition_fee = 52400,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = 'Academic Requirements<p>Units 3 and 4: a study score of at least 25 in one of Biology, Chemistry, any Mathematics, Physical Education, Physics or Health and Human Development.</p><p>Units 3 and 4: a study score of at least 30 in English (EAL) or at least 25 in English other than EAL.</p> English Language Requirements<p>IELTS is the only English Proficiency test accepted for entry into this course.</p><br/><p>Please refer to our <a href="https://www.latrobe.edu.au/study/apply/international/requirements">Language requirements</a> page for details of other accepted English proficiency tests and additional recognised English language proficiency measures, such as English as the language of instruction.</p><br/><p>7.5 IELTS (Academic) with no individual band less than 7.0.</p>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '0101264';

UPDATE courses SET
    course_description = '<p>Gain an in-demand skill set to design, implement and manage digital health solutions that meet the evolving healthcare needs of individuals and communities with La Trobe''s Master of Digital Health.</p><p>Advance your knowledge in new and emerging areas of digital health, including health analytics, virtual care, the Internet of Medical Things (IoMT), websites, apps and social media. Explore these technologies and their applications by examining benefits, risks and their ethical and legal implications. Tailor your degree to your career goals with a range of practical specialisations and electives, from data analytics, cybersecurity and artificial intelligence (AI) to management, strategy, policy and opportunities to apply your learning by working on real-world digital health solutions with industry.</p><p>By completing La Trobe''s Master of Digital Health, you will:</p><ul><li>embrace a design-thinking mindset, using data-driven, human-centered and experience-based approaches to solutions</li><li>gain an understanding of big data health analytics and explore how it can be applied to real-world applications</li><li>discover powerful tools to effectively communicate health information to different audiences in the digital age </li><li>assess organisational preparedness for digital transformation and know how to plan and conduct successful digital transformation programs</li><li>graduate ready to work at the forefront of a progressive and secure healthcare system.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
