UPDATE courses SET
    course_description = '<p>In La Trobe''s Master of Biotechnology and Bioinformatics, you''ll learn to harness new and emerging technologies in human health, diagnostics, sustainability, food security and renewable energy.</p><p>Develop the human skills and technical expertise to launch a career in a range of exciting industries. From biological products to pharmaceuticals, agriculture to nutrition: you''ll be prepared to work in the fields that rely on this fast-growing area of science.</p><p>This degree gives you more than flexibility in your career – it also gives you flexibility in how you study. In your final year, you could take an advanced bioinformatics pathway. Or you could choose the research project pathway instead, enjoying unrivalled access to industry networks and researchers in the field and benefiting from 25-30 hours of laboratory time each week.</p><p>If you decide you want to head straight into the workforce, you could even exit with a Graduate Diploma in Biotechnology and Bioinformatics after successfully completing the first year of this degree.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Bioinformatics</strong><ul><li>Use industry-standard bioinformatics software to address biological problems.</li></ul></li><li><strong>Practical biotechnology</strong><ul><li>Gain practical skills in PCR, cloning, protein expression, protein purification and immunoblotting laboratory techniques.</li></ul></li><li><strong>Scientific communication skills</strong><ul><li>Build your expertise in writing reports and presenting data.</li></ul></li><li><strong>Proteomics and genomics</strong><ul><li>Explore advanced technologies such as CRISPR-mediated gene editing, next generation sequencing and mass spectrometry.</li></ul></li><li><strong>Protein chemistry</strong><ul><li>Practice the laboratory techniques used in purifying and characterising protein preparations.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 90800,
    onshore_tuition_fee = 45400,
    enrolment_fee = 0,
    materials_fee = NULL,
