UPDATE courses SET
    course_description = '<p>Designed to help you build our digital future, La Trobe''s Bachelor of Information Technology equips you with skills across programming, networking, databases, systems analysis and design, and project management.</p><p>Along with building a strong set of core IT skills you can choose to major in one of several areas aligned to future industry growth including artificial intelligence, cloud analytics, cybersecurity, network engineering or information systems.</p><p>Broaden your knowledge and capabilities further through a wide range of electives. Combine your core IT skills with business, social sciences, humanities, web engineering, computer technology, security and information systems analysis subjects. Plus you could develop a software program of your own, which you could present at the annual Engineering and IT Showcase to potential employers.</p><p>With industry-based projects and CISCO certification embedded in the course, you''ll receive professional mentoring opportunities as you build career ready skills. You''ll also gain access to our expert research centres, including the Centre for Technology Infusion and our state-of-the-art Technology Innovation Lab for the Internet of Things – developed in collaboration with Microsoft and CISCO.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Web and software development</strong><ul><li>Develop and build websites and software. Administer the front end, back end and server side of websites and IT systems.<br/><br/></li></ul></li><li><strong>IT systems analysis and design</strong><ul><li>Understand and analyse IT systems to deliver more efficient and effective IT solutions for your organisation.<br/><br/></li></ul></li><li><strong>Design</strong><ul><li>Learn about software, system and network design so you can contribute to making better programs and infrastructure.<br/><br/></li></ul></li><li><strong>Programming and networking</strong><ul><li>Learn the language of computers and how they communicate with one another to create working code and smarter systems.<br/><br/></li></ul></li><li><strong>Project management, estimation, documentation and report evaluation</strong><ul><li>IT is more than just computers. Learning to manage projects and communicate effectively is a must in any organisational environment.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 7 - Bachelor Degree.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 126000,
    onshore_tuition_fee = 42000,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>Units 3 and 4: a study score of at least 25 in English (EAL) or at least 20 in English other than EAL.</td></tr><tr><td><strong>English Proficiency</strong></td><td>6.0 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
