WHERE cricos_course_code = '049940G';

UPDATE courses SET
    course_description = '<p>If you''re a practitioner in clinical sciences in: Occupational Therapy, Physiotherapy, Prosthetics and Orthotics, Podiatry, Speech Pathology, Audiology, Orthoptics, or Food, Nutrition and Dietetics, this degree provides you with an opportunity to extend your professional practice through an integrated program of theory, practice and research.</p><p>The degree offers an integrated program of research with supporting coursework in the first year. Through a combination of core and elective subjects, you''ll gain knowledge and skills in designing and conducting research, literature review techniques, critical analysis and writing for publication, as well as opportunities to apply these skills in clinically-based professional projects.</p><p>You''ll pursue an independent and sustained investigation into a research problem that will culminate in the submission of a thesis for examination of 60,000 words.</p><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 10 – Professional Doctorate.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 180000,
