UPDATE courses SET
    course_description = '<p>Help individuals and communities to maximise productivity, wellbeing and quality of life with La Trobe''s Master of Occupational Therapy Practice.</p><p>Open to students from any undergraduate discipline, you''ll graduate with a competitive edge through a combination of coursework and 1000 hours of hands-on, industry-responsive placements. Designed to meet the competencies for safe and effective practice, you''ll develop advanced knowledge and skills in assessment and intervention, the therapeutic use of occupation and the adaptation of environments.</p><p>Get hands-on with a six-week, full-time professional practice block in your first year, then two eight-week, full-time professional practice blocks and a ten-week project-based learning placement in your second year.</p><p>Subject to completion of local requirements, graduates may be eligible to apply to practice in other countries including the UK, North America and Sweden.</p><p>By completing La Trobe''s Master of Occupational Therapy Practice, you will:</p><ul><li>benefit from an integrated learning approach that reflects modern occupational therapy practice expectations</li><li>focus on four key themes: First Nations'' knowledge and cultural safety, evidence-based practice, occupation, and professionalism.</li><li>explore the theoretical foundations of occupational therapy, recognising the relationship between occupational participation, health and well-being</li><li>develop advanced skills in searching, appraising and integrating research evidence into practice</li><li>understand how to describe, critique and apply the principles of engagement, assessment, intervention and case management</li><li>learn how to integrate specialised knowledge, professional reasoning and professional behaviour within practice.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 101200,
    onshore_tuition_fee = 50600,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td><ul><li>IELTS, TOEFL, PTE are the only English Proficiency tests accepted for entry into this course.</li><li>Refer to Language requirements page for details of other accepted English proficiency tests and additional recognised English language proficiency measures, such as English as the language of instruction.</li><li>7.0 IELTS (Academic) with no individual band less than 7.0.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '062795B';

UPDATE courses SET
    course_description = '<p>Physiotherapists assess, diagnose and treat patients with movement disorders or disabilities, including those with temporary or long-term injuries and musculoskeletal, neurological, and cardiorespiratory conditions. Physiotherapists use a range of skills, including education and advice, movement or exercise prescription and manual therapy with the aim of assisting people to achieve their goals for recovery, activity, participation and quality of life. Physiotherapists may work independently or as members of multidisciplinary healthcare teams. They are active in the prevention of illness and injury and in the promotion of health, and are also involved in clinical research, movement rehabilitation, ergonomics and the management of healthcare organisations.<br/>Following an applied anatomy subject in Term 1 (Jan-Feb), the first year of the course will develop core knowledge and skills required for effective physiotherapy practice in a range of healthcare settings, across a variety of practice areas, and work with clients from across the lifespan. The second year of the course comprises integrated theory and clinical practice subjects, where advanced physiotherapy knowledge and skills will be developed and applied to clinical environments. </p><p>The clinical practice and theory subjects extend outside official University semester dates. The course includes small-group learning to master the practical aspects of physiotherapy practice. You will be expected to assess and treat patients in hospitals and other clinical settings under the supervision of a qualified clinician.</p><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 122400,
    onshore_tuition_fee = 57600,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = 'English Language Requirements<p>Please refer to our <a href="https://www.latrobe.edu.au/study/apply/international/requirements">Language requirements</a> page for details of other accepted English proficiency tests and additional recognised English language proficiency measures, such as English as the language of instruction.</p><br/><p>7.0 IELTS (Academic) with no individual band less than 7.0.</p><br/><p>IELTS, TOEFL and PTE are the only English Proficiency tests accepted for entry into this course.</p>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '111850A';

