UPDATE courses SET
    course_description = '<p>Shape the future of business with skills that matter.</p><p>Want to turn your passion for business and problem-solving into a career with real impact? La Trobe''s Bachelor of Accounting is your launchpad. Developed in close collaboration with industry partners, this degree doesn''t just teach accounting — it prepares you to lead in a world driven by data, digital innovation, and ethical decision-making.</p><p>Learn by doing — not just listening. From your first year, you''ll work with industry-standard cloud-based software and tackle real-world business challenges through immersive simulations and projects. You''ll explore how accounting shapes smart decisions in every part of a business — and why it''s at the heart of every successful organisation.</p><p>Small, supportive classes mean you''ll connect closely with your lecturers and peers, building confidence through active learning and real collaboration. With flexible majors, minors, and electives, you can customise your degree to suit your passions — whether that''s finance, tech, sustainability, or strategy.</p><p>Get industry-ready with hands-on experience. You could complete a work placement with leading firms, government agencies, or social enterprises. Many students have already made their mark with top-tier multinationals, regional firms, and international businesses — gaining skills, networks, and career clarity.</p><p>By graduation, you won''t just understand accounting — you''ll know how to use it to drive performance, solve problems, and lead with purpose.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Digital accounting systems</strong><ul><li>Understand tech-driven processes, internal controls, and governance</li></ul></li><li><strong>Accounting processes</strong><ul><li>Record, report and analyse transactions using cloud-based tools</li></ul></li><li><strong>Financial accounting</strong><ul><li>Tackle complex reporting and evaluate real-world financial practices</li></ul></li><li><strong>Management accounting</strong><ul><li>Use data to plan, measure and optimise business performance</li></ul></li><li><strong>Audit &amp; forensic accounting</strong><ul><li>Explore assurance services and fraud detection techniques</li></ul></li><li><strong>Taxation</strong><ul><li>Learn how income tax impacts individuals and businesses, including Capital Gains Tax and Fringe Benefit Tax</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 7 - Bachelor Degree.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 129000,
    onshore_tuition_fee = 43000,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>Units 3 and 4: a study score of at least 25 in English (EAL) or at least 20 in English other than EAL.</td></tr><tr><td><strong>English Proficiency</strong></td><td>6.0 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
