UPDATE courses SET
    course_description = '<p>Build on your successes in the Bachelor of Psychological Science by completing Honours to enhance essential employability skills or take your first step to a career in research, academia and beyond.</p><p>You''ll gain a deeper understanding of research theory, design and practice principles introduced in your undergraduate degree. You''ll study advanced theory in psychology and take part in a tailored psychology research methodology seminar. To apply your research knowledge and skills, you''ll undertake an original research project under the supervision of expert staff from La Trobe''s School of Psychology and Public Health to produce evidence-based solutions to current issues in psychology.</p><p>By graduating with Honours, you''ll not only gain an edge in an increasingly competitive job market, you''ll also have the opportunity to advance to further coursework or research at Master''s level or, for high achievers, direct entry into a PhD.</p><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 – Bachelor Degree Honours.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 42000,
