UPDATE courses SET
    course_description = '<p>Take the first step in your engineering career with La Trobe''s Bachelor of Civil Engineering (Honours).</p><p>Become an expert as you build your knowledge in a wide range of engineering specialties. Understand the technical aspects of geotechnics and hydraulic systems. Develop strong foundations in structural and electrical engineering. And explore the countless possibilities of mechanical engineering.</p><p>You''ll also develop a specialised skillset that''s focused on creating sustainable, efficient and durable systems. Understand the importance of high-quality infrastructure design, civil construction and computer-aided design.</p><p>You''ll learn from leading academics in small classes, giving you an invaluable intimate learning experience. As you progress, you''ll have the opportunity to undertake research in sustainability, urban irrigation, and advances in concrete technologies.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Sustainable infrastructure</strong><ul><li>Learn the fundamentals of the design and production of renewable energy systems.<br/><br/></li></ul></li><li><strong>Civil construction</strong><ul><li>Develop your knowledge of design, and explore both practical and project management perspectives.<br/><br/></li></ul></li><li><strong>Water resources</strong><ul><li>Learn about fluid dynamics, hydraulic systems, hydrological cycles, water quality, water management and water treatment.<br/><br/></li></ul></li><li><strong>Transport engineering</strong><ul><li>Analyse and design multimodal transport facilities, road and pavement structures.<br/><br/></li></ul></li><li><strong>Computer-aided design</strong><ul><li>Use computers and software to design, improve and assess projects.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 – Bachelor Degree Honours.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 172000,
    onshore_tuition_fee = 43000,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = 'Academic Requirements<p>Units 3 and 4: a study score of at least 20 in one of Maths: General Mathematics, Mathematical Methods or Specialist Mathematics.</p><p>Units 3 and 4: a study score of at least 25 in English (EAL) or at least 20 in English other than EAL.</p> English Language Requirements<p>6.0 IELTS (Academic) with no individual band less than 6.0.</p>',
    apply_form = 'https://student-latrobe.studylink.com',
