UPDATE courses SET
    course_description = '<p>Learn how to provide essential oral healthcare with La Trobe''s accredited Bachelor of Oral Health Science. Studying in an inter- and intradisciplinary setting, you''ll develop your professional practice at Australia''s largest rural health school.</p><p>Develop your understanding of oral health promotion, and the prevention and treatment of oral diseases. Get hands-on experience in clinical placements across regional Victoria and treat patients under the supervision of experienced clinicians. Your scope of practice includes dental therapy treatments to patients of all ages.</p><p>Note: You''ll need to complete your Level 1 First Aid/CPR certification, get your required vaccinations, and provide a current police check and Working with Children Check before starting this degree.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Preventive oral health</strong><ul><li>Develop your knowledge of preventive, periodontal and restorative procedures.</li></ul></li></ul><ul><li><strong>Medicine for dentistry</strong><ul><li>Learn to take a comprehensive medical history, understand its role in safe oral healthcare, and the link between oral and general health.</li></ul></li></ul><ul><li><strong>Clinical practice</strong><ul><li>Discover how to diagnose and plan care for patients. Improve your communication and treatment skills while learning to manage patients in a clinical setting.</li></ul></li></ul><ul><li><strong>Global perspectives in oral health</strong><ul><li>Gain insight into different cultures and explore your role as an oral health therapist in a multicultural society. Further develop your cultural competence through an elective rural, interstate or overseas placement.*</li></ul></li></ul><p>*Subject to government restrictions on international travel.</p><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 7 - Bachelor Degree.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 144600,
    onshore_tuition_fee = 48200,
    enrolment_fee = 0,
    materials_fee = NULL,
