UPDATE courses SET
    course_description = '<p>Data science professionals are in high demand in today''s data-driven world. Whether you''re already working in data science, or you''re ready to make a career change, our Master of Data Science prepares you for a successful career in this exciting field.</p><p>Designed in collaboration with our industry partners, this degree gives you the knowledge, skills and hands-on experience to transition from university to the workplace. And with two early exit points along the way, you can be sure that every subject is contributing to your career.</p><p>You''ll build fundamental skills in programming, databases, probability, statistics, data exploration and analysis. Got a particular interest in artificial intelligence, bioinformatics or sport analytics? This degree allows you to specialise in these areas and others, such as big data and cloud computing, business applications and data modelling and analytics.</p><p>As you study, you''ll have opportunities to work with our industry partners on real-world projects and take on an industry work placement. If your sights are set on a research career, you can choose to undertake a thesis in computer science or statistics.</p><p>Every step of the way, our supportive and highly qualified teaching staff will be there to offer ongoing support and advice.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Data science</strong><ul><li>Get practical experience with open-source software and platforms, including Python, R and Hadoop.</li><li>Understand database fundamentals, programming languages such as Java and Python, and cloud-based services offered by Amazon, Google, IBM and Microsoft.</li></ul></li></ul><ul><li><strong>Mathematics and statistics</strong><ul><li>Learn how to create complex models and use powerful tools for advanced analysis and problem-solving.</li><li>Build your skills using real data sets from our industry partners and learn how to solve data challenges facing businesses and organisations.</li></ul></li></ul><ul><li><strong>Project management</strong><ul><li>Learn how to manage large-scale IT projects and work in a team to develop a small-scale, industry-based system.</li></ul></li></ul><ul><li><strong>Complementary skills in other disciplines</strong><ul><li>Boost your knowledge through electives in business, health sciences, artificial intelligence and cybersecurity.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 87600,
    onshore_tuition_fee = 43800,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td>6.5 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '092396B';

UPDATE courses SET
    course_description = '<p>Take advantage of the interconnected worlds of commerce and technology through La Trobe''s Bachelor of Commerce/Bachelor of Computer Science.</p><p>Co-designed with industry leaders, our Bachelor of Commerce/Bachelor of Computer Science gives you a a multidisciplinary set of skills and knowledge sought-after by employers and policymakers. You''ll develop a comprehensive understanding of the principles underpinning the tech market, as well as the scientific principles behind computer hardware and software.</p><p>By completing La Trobe''s Bachelor of Commerce/Bachelor of Computer Science, you will:</p><ul><li>learn how to identify practical solutions to real-world challenges, improve your ability to negotiate with stakeholders and communicate your solutions</li><li>explore topics such as programming, mathematics, statistics and data analytics</li><li>prepare to become an effective leader who can meet the challenges of automation, AI-driven technologies and big data</li><li>build critical skills in independent research, innovative thinking, cultural intelligence, oral and written communication, teamwork and leadership</li><li>gain real-world experience through industry placements, work-integrated learning projects and overseas student exchange opportunities</li><li>graduate ready to apply for membership into the Australian Computer Society (ACS) and, depending on your choice of majors, a range of business professional associations.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 7 - Bachelor Degree.</p>',
