UPDATE courses SET
    course_description = '<p>La Trobe''s Graduate Diploma in Sport Analytics is a formal qualification with hands-on experience with real sport datasets, and in-demand technical training in programming, databases, machine learning, and statistical analysis— all delivered flexibly with a mix of online and on-campus study suited to working professionals.</p><p>Learn how to use data to boost athlete performance and wellbeing. You''ll get hands-on experience with industry-standard technologies and cutting-edge sport analytics technology like Catapult GPS and LPS, Hudl SportsCode and IMeasureU (Inertial measurement units).</p><p>The course aims to prepare you for roles in the field of sport analytics or for currently employed sport and exercise professionals looking to advance into higher roles through a formal education and qualification in sports analytics. You''ll graduate with a direct pathway into the Master of Sport Analytics or ready to use your new data analytics skills in the sport industry you''re passionate about.</p><p>By studying La Trobe''s Graduate Diploma in Sport Analytics, you''ll learn:</p><ul><li><p>Sport analytics in practice</p><ul><li><p>Learn about contemporary technology applications, and apply theoretical understanding of analytics processes and methodologies to authentic sport-related data sets.</p></li></ul></li><li><p>Advanced analytics</p><ul><li><p>Develop enhanced skills in data warehousing, and analytical skills including coding (R and Python), machine learning and statistical modelling.</p></li></ul></li><li><p>Analytical methods in sport</p><ul><li><p>Learn how to perform various data handling techniques, statistical tests and explore data visualisation techniques within a sport and exercise science context.</p></li></ul></li><li><p>Database management</p><ul><li><p>Gain an overview of the architecture and management of database systems and explore programming foundations to design and create software solution.</p></li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 - Graduate Diploma.</p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = 42200,
    onshore_tuition_fee = 42200,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td>6.5 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
