UPDATE courses SET
    course_description = '<p>Explore the close connections between crime and the human mind and its effects on behaviour with La Trobe''s multidisciplinary Bachelor of Criminology/Bachelor of Psychological Science.</p><p>Understand crime in its broader social context and how individual and social responses are shaped by gender, race, power and money. Establish a grounding in psychology, exploring theories on individuals, groups and whole societies. Learn how experiences and incentives impact behaviour and how this knowledge can be applied to key issues in criminal justice.</p><p>By completing La Trobe''s Bachelor of Criminology/Bachelor of Psychological Science, you will:</p><ul><li>investigate the complex causes of crime, principles of crime prevention and policy, and how social factors intersect with our criminal justice system</li><li>explore the role of courts, police, prisons and how deviance and crime are understood by different parts of society</li><li>develop valuable expertise in cognitive, developmental, social, abnormal, clinical and health psychology</li><li>get on-the-job experience with work placement opportunities at organisations like the Victims of Crime Tribunal</li><li>have the flexibility to study online, on campus or a mix of both</li><li>graduate ready to apply for membership of the Australian Psychological Society (APS) and the prerequisites to apply for Honours in psychology, with potential to pursue postgraduate study and registration as a psychologist.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 7 - Bachelor Degree.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 168000,
    onshore_tuition_fee = 42000,
