UPDATE courses SET
    course_description = '<p>Stand out with a law degree committed to social impact and community engagement. Our dedicated four-year Law (Honours) degree gives you a strong academic and professional foundation with the ability to match your legal career to your area of interest through a range of specialised electives.</p><p>Put your legal skills to the test with hands-on practical learning opportunities through our Legal Internship Program, work-based learning, the Law Clinic, overseas study programs, and leading mooting program.</p><p>You''ll also apply your training into the real world with internships, clerkships, and practical placements at legal firms, government bodies, and community legal centres – giving you enhanced employability and professional readiness through our network of industry and community partnerships.</p><p>Combine intellectual and skills-based legal training with a progressive approach to law. With a strong focus on practical skills like dispute resolution, criminal procedure, and contract law, you''ll learn what it is like to work on real cases and develop the professional skills to meet the demands of legal practice.</p><p>By studying La Trobe''s Bachelor of Laws (Honours), you will:</p><ul><li>develop key skills in negotiation and examine the processes of arbitration, conciliation and mediation in private and commercial disputes</li><li>build your understanding of the criminal justice system, apply criminal law to real-world scenarios and provide legal advice</li><li>apply the legal principles governing the creation, interpretation and termination of a contract</li><li>hone your skills in critical thinking, research, writing and teamwork, then apply them with work-integrated learning opportunities in community legal centres, law firms and government agencies.</li><li>join our leading moot court program, with opportunities to take part in competitions both nationally and internationally.</li><li>benefit from a supportive learning environment that prioritises student wellbeing and academic success.</li><li>complete the subjects required by the Victorian Legal Admissions Board (VLAB) to meet the requirements for admission to the legal profession in Victoria.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 – Bachelor Degree Honours.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 174400,
    onshore_tuition_fee = 43600,
    enrolment_fee = 0,
    materials_fee = NULL,
