UPDATE courses SET
    course_description = '<p>La Trobe''s Bachelor of Global Studies gives you a strong grounding in the issues facing key regions and countries around the world. We''ve designed this degree to introduce you to global problems and their policy responses, so you''ll develop the tools to tackle the challenges of the future.</p><p>Study core subjects examining the history of international relations and geopolitics, contemporary security issues – such as American power, the rise of China, contemporary armed conflict and terrorism – and the emerging challenges of human and environmental security.</p><p>Look at international cooperation and conflict. Analyse the dynamics of power, sovereignty and security, exploring transformational changes in 21st century international relations. Investigate the powerful role of international law – including humanitarian, environmental and refugee law.</p><p>Whatever your ambition, tailor your degree with specially curated majors and minors that allow you to explore the geopolitical and humanitarian forces shaping our world. Choose from majors such as international relations, human rights, conflict and negotiation, Asian politics and security, government and policy, sustainability and development, Chinese, Japanese, Hindi, Spanish, Greek, French and Italian.</p><p>Global experiences are a vital part of global studies. Get out of the classroom and into the real world with a study experience at one of our overseas partner universities and build both your skills and your professional network. You''ll also have the opportunity to do an internship, either in Australia or overseas, that''s tailored to your career goals.<a href="#_ftn1">[1]</a></p><p><strong>You''ll learn:</strong></p><ul><li><strong>Global issues and organisations</strong><ul><li><p>Explore the complex systems, structures, laws and practices that shape global issues. Broaden your understanding and consider a range of political, social, legal and cultural perspectives.</p></li></ul></li></ul><ul><li><strong>Problem solving and critical thinking</strong><ul><li>Learn how to identify and analyse international and global problems and formulate responses to them.</li></ul></li></ul><ul><li><strong>Theory and practice of politics</strong><ul><li>Build your understanding of political systems, actors and processes. Understand how they work at a local, national and global level.</li></ul></li></ul><ul><li><strong>Grassroots development and sustainability</strong><ul><li>Explore how global decisions can impact individual communities and the environments we all depend on.</li></ul></li></ul><p><a href="#_ftnref1">[1]</a> Subject to government restrictions on international travel.</p><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 7 - Bachelor Degree.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 107400,
    onshore_tuition_fee = 35800,
    enrolment_fee = 0,
