UPDATE courses SET
    course_description = '<p>Tackle real-world logistics and supply chain challenges while using emerging analytics technologies to transform business practice with La Trobe''s Master of Logistics and Supply Chain Management.</p><p>Designed and delivered in consultation with industry professionals, you''ll gain direct exposure to the logistics and supply chain sector through field trips to ports and distribution centres, guest lectures, hands-on assessments, and optional industry placements.</p><p>Explore topics across AI, blockchain, Internet of Things, cybersecurity governance and applied data analytics, covering the technical skills while exploring the ethical, environmentally responsible supply chain innovation through integrated circular economy and carbon accountability practices — preparing you for future-ready roles at the forefront of Industry 5.0 innovations.</p><p>You''ll benefit from tailored pathways depending on your professional experience and prior learning with options to complete your Master''s degree in 1 or 1.5 years or exit early with a Graduate Certificate or Graduate Diploma. You''ll also study through a combination of online and on campus classes with full-or part-time study options – giving you greater flexibility to balance work and life commitments.</p><p>By studying La Trobe''s Master of Logistics and Supply Chain Management, you will:</p><ul><li>master sustainable and responsible business practice and the circular economy in a national and global context</li><li>build strong foundational expertise across all key areas of supply chain strategy, including logistics, sourcing, marketing, ICT, and customer service</li><li>develop broad managerial skills in human resource management, project management, and quality control to prepare for leadership roles in complex, global supply networks</li><li>gain hands-on data analytics skills using real-world tools and techniques, such as data visualisation, predictive analytics, and business analytics applications specific to logistics and supply chain contexts</li><li>understand the impact of digitalisation and technologies like artificial intelligence (AI), digital twins and cloud computing to unlock valuable insights</li><li>engage in industry-led experiential and work-integrated learning, including coaching and networking opportunities and access to graduate programs with our partners.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 94400,
    onshore_tuition_fee = 47200,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td>6.5 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
