UPDATE courses SET
    course_description = '<p>If you''re keen to launch your career in engineering, La Trobe''s Associate Degree in Engineering Technology will give you solid foundations for success and a pathway to a world-class Bachelor''s degree in engineering.</p><p>Learn how to tackle the big problems faced by engineers every day. Develop essential skills in maths, physics and computer programming. Then set yourself apart from other graduates when you learn valuable human skills in innovation, business management and leadership.</p><p>In this highly practical degree, you''ll collaborate with multidisciplinary teams and develop your problem-solving skills. Explore the impacts of climate change and find innovative engineering solutions to help create sustainable societies. You''ll work with real-world engineering systems and learn current best practice from leading engineering experts.</p><p>Develop your written and oral communication skills. You''ll build your confidence in relaying complex technical information and explore the technical, financial, legal and environmental impacts of engineering innovations.</p><p>Get a degree that''s recognised by industry. Graduates can apply for membership with Engineers Australia as an Engineering Associate.</p><p>Once you''ve completed your Associate Degree, you''ll be eligible to apply to La Trobe''s Bachelor of Civil Engineering (Honours) you will then be able to apply for advanced standing to commence Bachelor studies at third year where you can further enhance your industry knowledge and experience by undertaking large-scale projects and work placements.</p><p>Get ready for a bright career in engineering.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Programming for engineers and scientists </strong><ul><li>Design and create software solutions to real-life problems, using programming languages such as Python.</li></ul></li><li><strong>Computer-aided design (CAD) </strong><ul><li>Harness the computer tools to design, simulate and model an engineered product.</li></ul></li><li><strong>Engineering enterprise </strong><ul><li>Learn how to become an engineering business leader. Explore business strategies for engineers, management tools and resources, the legal system, marketing and finance.</li></ul></li><li><strong>Sustainability and renewable energy design </strong><ul><li>Learn about climate change, sustainability and renewable energy design, and join a multidisciplinary team on a renewable energy project.</li></ul></li><li><strong>Systems modelling </strong><ul><li>Develop your modelling skills using software tools such as MATLAB and Simulink. Model and investigate engineering systems related to a broad range of real-world engineering systems.</li></ul></li><li><strong>Engineering design and problem solving </strong><ul><li>Examine current engineering practices and develop your creative engineering design skills through an industry research project.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 6 - Associate Degree.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 86000,
    onshore_tuition_fee = 43000,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Units 3 and 4: a study score of at least 25 in English (EAL) or at least 20 in English other than EAL.</li><li>Units 3 and 4: a study score of at least 20 in any Mathematics.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td>6.0 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
