WHERE cricos_course_code = '107090D';

UPDATE courses SET
    course_description = '<p>Combine practical, progressive and multidisciplinary legal skills with a unique social and ethical perspective on how the law works with La Trobe''s Bachelor of Laws (Honours)/Bachelor of Politics, Philosophy and Economics.</p><p>Gain a powerful skillset in dispute resolution, evidence and criminal procedure, contract law, company law and public law. Enhance your political expertise by learning how governments manage the economy and achieve important social objectives. Gain first-hand experience with work placement opportunities in law firms, community legal centres, courts and other government agencies.</p><p>By studying La Trobe''s Bachelor of Laws (Honours)/Bachelor of Politics, Philosophy and Economics, you will:</p><ul><li>develop key skills in negotiation and examine the processes of arbitration, conciliation and mediation in private and commercial disputes</li><li>understand constitutional law and how government power is distributed, exercised and controlled</li><li>explore philosophy and critical thinking, improve your ability to reason empathetically and reflect clearly on complex issues</li><li>build your knowledge of political systems, how countries are governed, and the forces and players that influence policy</li><li>complete the subjects required by the Victorian Legal Admissions Board (VLAB) to meet the requirements for admission to the legal profession in Victoria</li><li>graduate with two degrees in only five years to gain a competitive career edge, with options in a wide range of industries.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 – Bachelor Degree Honours.</p>',
    course_duration_per_week = 260,
    offshore_tuition_fee = 218000,
    onshore_tuition_fee = 43600,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>Units 3 and 4: a study score of at least 30 in English (EAL) or at least 25 in English other than EAL.</td></tr><tr><td><strong>English Proficiency</strong></td><td>6.5 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
