    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td>6.5 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '107139C';

UPDATE courses SET
    course_description = '<p>If you''re looking to pursue a rewarding career in the field of archaeology, La Trobe''s Master of Archaeology will prepare you for a career as a professional archaeologist, heritage manager or researcher.</p><p>You''ll develop specialist skills in contemporary archaeological practice and acquire comprehensive knowledge of Australian and Australian Indigenous archaeology.</p><p>You''ll learn from renowned researchers in La Trobe''s world-class facilities and benefit from both a hands-on and academic perspective.</p><p>For students interested in a global career in archaeology, the Master of Archaeology can be tailored to meet your needs. Develop strong field skills applicable anywhere in the world while undertaking specialist research into your preferred region and time period.</p><p>Choose from a wide range of subjects and undertake specialist studies in heritage planning, community consultation, field techniques, analysis of human and animal bone, site identification and recording using digital technologies.</p><p><strong>You''ll learn:</strong></p><ul><li><strong>Aboriginal and historic archaeology</strong><ul><li>Delve into Indigenous Australian and historic archaeology. Examine past practice and contemporary advances and findings.</li></ul></li><li><strong>Cultural heritage management</strong><ul><li>Learn to navigate and guide others in the ethical and regulatory requirements of managing sites and objects of cultural importance.</li></ul></li><li><strong>Archaeological field methods</strong><ul><li>Build the practical skills and knowledge you need to conduct archaeological fieldwork in Australia and overseas.</li></ul></li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
