UPDATE courses SET
    course_description = '<p>Develop the clinical understanding to care for people across the lifespan while building expertise in human behaviour and psychological science with La Trobe''s Bachelor of Nursing/Bachelor of Psychological Science. </p><p>In this double degree, you will combine nursing practice with psychological science to understand how health, behaviour, communication and wellbeing interact in real-world care. </p><p>You will learn through clinical simulation and 800 hours of supervised placement, with potential (but not guaranteed) settings including hospitals, community health services, aged care, rehabilitation and mental health. </p><p>By studying the Bachelor of Nursing/Bachelor of Psychological Science, you will learn how to: </p><ul><li>apply nursing knowledge across acute care, chronic illness, rehabilitation, community health, emergency care, mental health and Indigenous health </li><li>analyse cognitive, developmental, social, abnormal, clinical and health psychology in healthcare and wellbeing contexts </li><li>evaluate evidence, health information and psychological assessment information to support person-centred care </li><li>interpret behavioural, psychosocial and cultural factors that shape health, communication and therapeutic engagement </li><li>develop clinical reasoning, teamwork, leadership and decision-making skills through simulation and supervised placement </li><li>communicate with patients, families and healthcare teams in complex clinical and community environments. </li></ul><p><strong>Please note: </strong>Clinical placements are allocated solely in accordance with the Bachelor of Nursing course structure and placement requirements, as there are no clinical placements associated with the Bachelor of Psychological Science. </p><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 7 - Bachelor Degree.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = 178400,
    onshore_tuition_fee = 44600,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>Units 3 and 4: a study score of at least 30 in English (EAL) or at least 25 in English other than EAL.</td></tr><tr><td><strong>English Proficiency</strong></td><td>IELTS of 7.0 with no individual band score less than 7.0 (can be across 2 sittings in a 6-month period, but no score can be below 6.5 and overall score must be 7 in both sittings)</td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '113662M';

UPDATE courses SET
    course_description = '<p>Build marketing knowledge and skills needed to expand your career opportunities and become a marketing leader with La Trobe''s Graduate Certificate in Marketing.</p><p>To thrive in today''s digital and data-driven environment, marketers need more than creative instinct: they need strategic insight, technological fluency, and an understanding of the risks and opportunities shaping modern business. In six months, this short postgraduate course equips you with the foundational tools and emerging knowledge to navigate contemporary marketing practice with confidence.</p><p>By completing La Trobe''s Graduate Certificate in Marketing, you will:</p><ul><li>develop a strong grounding in marketing management, including how to evaluate marketing strategies and make evidence-based decisions</li><li>gain insight into digital marketing tools, platforms and performance metrics to design and manage high-impact campaigns</li><li>explore the potential of artificial intelligence in transforming marketing practices and customer engagement</li><li>understand how cybersecurity and data governance shape trust, privacy, and brand integrity in digital marketplaces.</li></ul><p>Successfully completing the Graduate Certificate in Marketing allows you to pursue further postgraduate study with credit, including our Master of Marketing.</p><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 8 - Graduate Certificate.</p>',
    course_duration_per_week = 26,
    offshore_tuition_fee = 23600,
    onshore_tuition_fee = 23600,
    enrolment_fee = 0,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td>6.5 IELTS (Academic) with no individual band less than 6.0.</td></tr></tbody></table>',
    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '113897C';

UPDATE courses SET
    course_description = '<p>Get the right mix of engineering know-how and business acumen to drive innovation across industries with La Trobe''s accredited Master of Manufacturing Engineering.</p><p>Designed and delivered in consultation with industry leaders, our Master''s equips you to meet contemporary manufacturing challenges using revolutionary technologies like artificial intelligence, robotics and machine learning. You''ll gain proficiency in system design, materials processing and sustainable engineering while enhancing your employability with enterprise skills in consultation, negotiation, risk and project management. You''ll also have the opportunity to experience engineering practice first-hand and build valuable industry connections with the option of an 800-hour work-integrated learning (WIL) program.</p><p>By completing La Trobe''s Master of Manufacturing Engineering, you will:</p><ul><li>gain an understanding of Australian engineering industry sustainability practices</li><li>build capabilities in aerospace, defence, industrial automation and robotics, automotive and precision engineering</li><li>master the design of automated production lines to improve quality and reduce costs</li><li>hone your skills in computer-aided engineering (CAE) software and tech to improve design, modelling, manufacturing, and control</li><li>graduate ready to apply for membership of Engineers Australia.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 92000,
