    apply_form = 'https://student-latrobe.studylink.com',
    updated_at = NOW()
WHERE cricos_course_code = '113898B';

UPDATE courses SET
    course_description = '<p>Get the skills and knowledge to meet the challenges of disruptive technologies that are reshaping industries and the engineering profession globally with La Trobe''s accredited Master of Civil Engineering.</p><p>Designed and delivered in consultation with industry leaders, our Master''s builds the capabilities and specialist expertise to meet society and industry demands to develop infrastructure faster, better and more sustainably. You''ll learn to analyse real-world problems and design modern infrastructure, developing valuable skills transferable across industries. You''ll also have the opportunity to experience engineering practice first hand and build valuable industry connections with the option of an 800-hour work-integrated learning (WIL) program.</p><p>By completing La Trobe''s Master of Civil Engineering, you will:</p><ul><li>gain an understanding of Australian engineering industry sustainability practices</li><li>learn to analyse real-world problems and design modern infrastructure, developing valuable skills transferable across industries.</li><li>master the mechanics of the quality and nature of materials to guide appropriate selection</li><li>discover how to use soil improvement techniques to make infrastructure stronger and more reliable</li><li>develop capabilities in structural dynamics to ensure structures are safe and long-lasting</li><li>discover how water and waste technology can be used as sustainable engineering solutions</li><li>graduate ready to apply for membership of Engineers Australia.</li></ul><p>The qualification awarded on graduation is recognised in the Australian Qualifications Framework (AQF) as Level 9 - Masters Degree.</p>',
